                          int *ldv, int *ipntr, double *workd, double *workl);

static void csr_matvec(int n, const int32_t *indptr, const int32_t *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int32_t a = indptr[i];
        int32_t b = indptr[i + 1];
        for (int32_t j = a; j < b; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

/* Returns info (0/1 success). Fills work arrays; caller does extraction via scipy. */
int arpack_iterate(int n, int k, int ncv, int maxiter, double tol,
                   const int32_t *indptr, const int32_t *indices, const double *data,
                   double *resid, double *v, double *workd, double *workl, int *ipntr,
                   int *out_nconv, int *out_ido, int *out_info) {
    arpack_state st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = 0;       /* LM */
    st.ido = 0;
    st.info = 1;        /* resid supplied */
    st.bmat = 0;        /* I */
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    int ldv = n;
    for (;;) {
        ARNAUD_dnaupd(&st, resid, v, &ldv, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == 5) {
            int xs = ipntr[0];
            int ys = ipntr[1];
            csr_matvec(n, indptr, indices, data, workd + xs, workd + ys);
        } else if (ido == 2) {
            int xs = ipntr[0];
            int ys = ipntr[1];
            memcpy(workd + ys, workd + xs, (size_t)n * sizeof(double));
        } else if (ido == 4) {
            /* should not happen when info starts at 1 and resid given */
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
    }
    *out_nconv = st.nconv;
    *out_ido = st.ido;
    *out_info = st.info;
    return st.info;
}
